<?php require_once '../config/auth.php';$page_title='Schedule Follow-up';$base='../';$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO followups(customer_id,subject,type,due_at,status,notes,owner_id) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['customer_id'],trim($_POST['subject']),$_POST['type'],$_POST['due_at'],'pending',trim($_POST['notes']),$_SESSION['user_id']]);header('Location:index.php');exit;}include '../partials/header.php';?><div class="cardx"><h4>Schedule Follow-up</h4><form method="post"><div class="row g-3 mt-1"><div class="col-md-6"><label>Customer</label><select required class="form-select" name="customer_id"><option value="">Select</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Type</label><select class="form-select" name="type"><option>call</option><option>email</option><option>meeting</option><option>task</option></select></div><div class="col-md-8"><label>Subject</label><input required class="form-control" name="subject"></div><div class="col-md-4"><label>Due date/time</label><input required class="form-control" type="datetime-local" name="due_at"></div><div class="col-12"><label>Notes</label><textarea class="form-control" name="notes"></textarea></div></div><button class="btn btn-primary mt-4">Schedule</button></form></div><?php include '../partials/footer.php';?>